@Override // com.ultrabar.launch.common.communication.message.IMessage
public void onMessage(MessageContext messageContext, IReply iReply) {
    if (ProfileManager.batchSave(messageContext.parseArray(ProfileManager.ProfileDTO.class))) {
        success(iReply);
        reloadModuleProfile();
    } else {
        failure(iReply);
    }
}
